"""Column fixes (2026-11-14) in two result tables (regenerated byte-identical otherwise)."""
import csv
from pathlib import Path

import pytest

PS = Path(__file__).resolve().parents[1]


def test_p62_replay_csv_column_is_n_resim_launches():
    p = PS / "results/P6.2/replay.csv"
    if not p.is_file():
        pytest.skip("no replay.csv")
    head = next(csv.reader(open(p)))
    assert "n_resim_launches" in head and "n_lines" not in head


def test_ep2_gemv_q80_has_no_128B_per_miss_column():
    p = PS / "results/EP.2/gemv_q80.csv"
    if not p.is_file():
        pytest.skip("no gemv_q80.csv")
    head = next(csv.reader(open(p)))
    assert "l2_miss_B_over_weight_bytes" not in head and "dram_over_weight_bytes_q80" in head
